def price(kind, qty, discount="0"):
    if kind == "premium":
        base = 20 * qty
    elif kind == "bulk":
        base = 8 * qty
    else:
        base = 10 * qty
    try:
        pct = int(discount)
    except ValueError:
        return None
    return base - base * pct // 100

