def connect(url):
    if url.startswith("mem:"):
        return {"kind": "memory"}
    return {"kind": "remote"}


def close(conn):
    if conn["kind"] == "memory":
        conn["closed"] = True
    return conn


def lookup(conn, key):
    return (conn["kind"], key)

