import pytest

from pkg.store import close, connect, lookup


@pytest.fixture
def conn():
    c = connect("mem:db")  # only this fixture reaches the memory branch
    yield c
    close(c)  # only this teardown reaches close()


def test_lookup_memory(conn):
    assert lookup(conn, "k") == ("memory", "k")


def test_lookup_remote():
    assert lookup(connect("db://x"), "k") == ("remote", "k")

